import sys,json
d=json.load(sys.stdin)
def walk(n,depth=0):
    st=n.get('status','')
    if st in ('active','pending','blocked'):
        print(f\"{'  '*depth}{n.get('id')}  [{st}]  owner={n.get('owner','')!r}  {n.get('title','')[:60]}\")
    for c in n.get('children',[]):
        walk(c,depth+1)
items = d if isinstance(d,list) else d.get('items',d.get('roadmap',[d]))
if isinstance(items,dict): items=[items]
for it in items: walk(it)
"

